import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"横渠易说 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"横渠易说 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/004.md","filePath":"zh/classics/hengqu/004.md"}'),l={name:"zh/classics/hengqu/004.md"};function n(t,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>以西南为得明，乃安贞之德也；以东北为丧朋，虽得主有庆而不可怀也。西南土之位，东北木之位也。“西南得朋，东北丧朋”，江沱之间，有嫡不以其媵备数，是不能丧朋也；媵遇劳而无怨，却是能丧朋者，其卒啸也歌，是“乃终有庆”也。此妇人之教大者也。西南，致养之地，东北，反西南者也，阴阳正合，则阴相对者必阳也。“西南得朋”，是始以类相从而来也。“东北丧朋”，丧朋，相忘之义，听其自治，不责人，不望人，是丧其朋也，丧朋则有庆矣。江有沱、有汜、有渚，皆是始离而终合之象也。有嫡不以其媵备数，是不能丧朋；媵遇劳而无怨，是能丧朋也，以其能丧朋，故能始离而终合。“之子归”，自嫡也；“不我以”，“不我与”，“不我过”，皆言其始之不均一也。“其后也悔”，嫡自悔也。处，“既安既处”之处也，始离而终既处也。歌是“乃终有庆”，庆则同有庆。</p><p>彖曰：至哉坤元!万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。牝马地类，行地无疆。柔顺利贞，君子攸行。先迷失道，后顺得常。</p><p>坤先迷不知所从，故失道；后能顺听，则得其常矣。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。</p><h3 id="象曰-地势坤-君子以厚德载物。" tabindex="-1">象曰：地势坤，君子以厚德载物。 <a class="header-anchor" href="#象曰-地势坤-君子以厚德载物。" aria-label="Permalink to “象曰：地势坤，君子以厚德载物。”">​</a></h3><h3 id="初六-履霜坚冰至。-象曰-履霜坚冰-阴始凝也-驯致其道-至坚冰也。" tabindex="-1">初六，履霜坚冰至。 象曰：“履霜坚冰”，阴始凝也，驯致其道，至坚冰也。 <a class="header-anchor" href="#初六-履霜坚冰至。-象曰-履霜坚冰-阴始凝也-驯致其道-至坚冰也。" aria-label="Permalink to “初六，履霜坚冰至。 象曰：“履霜坚冰”，阴始凝也，驯致其道，至坚冰也。”">​</a></h3><h3 id="六二-直方大-不习无不利。-象曰-六二之动-直以方也。-不习无不利-地道光也。" tabindex="-1">六二，直方大，不习无不利。 象曰：六二之动，直以方也。“不习无不利”，地道光也。 <a class="header-anchor" href="#六二-直方大-不习无不利。-象曰-六二之动-直以方也。-不习无不利-地道光也。" aria-label="Permalink to “六二，直方大，不习无不利。 象曰：六二之动，直以方也。“不习无不利”，地道光也。”">​</a></h3><p>地道之有孚者，故曰光也。</p><h3 id="六三-含章可贞-或从王事-无成有终。-象曰-含章可贞-以时发也。-或从王事-知光大也。" tabindex="-1">六三，含章可贞，或从王事，无成有终。 象曰：“含章可贞”，以时发也。“或从王事”，知光大也。 <a class="header-anchor" href="#六三-含章可贞-或从王事-无成有终。-象曰-含章可贞-以时发也。-或从王事-知光大也。" aria-label="Permalink to “六三，含章可贞，或从王事，无成有终。 象曰：“含章可贞”，以时发也。“或从王事”，知光大也。”">​</a></h3><p>六三以阴居阳，不独有柔顺之德，其知光大，含蕴文明，可从王事者也。然不可动以躁妄，故可静一以俟时；不可有其成功，故无成乃有终也。</p><h3 id="六四-括囊-无咎无誉。-象曰-括囊无咎-慎不害也。" tabindex="-1">六四，括囊，无咎无誉。 象曰：“括囊无咎”，慎不害也。 <a class="header-anchor" href="#六四-括囊-无咎无誉。-象曰-括囊无咎-慎不害也。" aria-label="Permalink to “六四，括囊，无咎无誉。 象曰：“括囊无咎”，慎不害也。”">​</a></h3><h3 id="六五-黄裳元吉。-象曰-黄裳元吉-文在中也。" tabindex="-1">六五，黄裳元吉。 象曰：“黄裳元吉”，文在中也。 <a class="header-anchor" href="#六五-黄裳元吉。-象曰-黄裳元吉-文在中也。" aria-label="Permalink to “六五，黄裳元吉。 象曰：“黄裳元吉”，文在中也。”">​</a></h3><h3 id="上六-龙战于野-其血玄黄。-象曰-龙战于野-其道穷也。" tabindex="-1">上六，龙战于野，其血玄黄。 象曰：“龙战于野”，其道穷也。 <a class="header-anchor" href="#上六-龙战于野-其血玄黄。-象曰-龙战于野-其道穷也。" aria-label="Permalink to “上六，龙战于野，其血玄黄。 象曰：“龙战于野”，其道穷也。”">​</a></h3><h3 id="用六-利永贞。-象曰-用六永贞-以大-中-终-也。" tabindex="-1">用六，利永贞。 象曰：“用六永贞”，以大(中)［终］也。 <a class="header-anchor" href="#用六-利永贞。-象曰-用六永贞-以大-中-终-也。" aria-label="Permalink to “用六，利永贞。 象曰：“用六永贞”，以大(中)［终］也。”">​</a></h3><p>文言</p><h3 id="坤至柔而动也刚-至静而德方-后得主而有常-含万物而化光。坤道其顺乎-承天而时行" tabindex="-1">坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行! <a class="header-anchor" href="#坤至柔而动也刚-至静而德方-后得主而有常-含万物而化光。坤道其顺乎-承天而时行" aria-label="Permalink to “坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行!”">​</a></h3><p>效法故光。 屈伸、动静、终始各自则，今以刚柔言之，刚何尝无静，柔何尝无动，“坤至柔而动也刚”，则柔亦有刚，静亦有动，但举一体，则有屈伸、动静、终始，乾行不妄，则坤顺必时也。</p><h3 id="积善之家-必有余庆-积不善之家-必有余殃。" tabindex="-1">积善之家，必有余庆；积不善之家，必有余殃。 <a class="header-anchor" href="#积善之家-必有余庆-积不善之家-必有余殃。" aria-label="Permalink to “积善之家，必有余庆；积不善之家，必有余殃。”">​</a></h3><p>余庆余殃，百祥百殃，与中庸必得之义同。善者有后，不善者无后，理当然，其不然者，亦恐迟晚中间。譬之瘠之或秀，腴之或不秀，然而不直之生也幸而免，遇外物大抵适然耳。君子则不恤，惟知有义理。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辩之不早辩也。</p><h3 id="易曰-履霜坚冰至-盖言顺也。直其正也-方其义也-君子敬以直内-义以方外" tabindex="-1">易曰“履霜坚冰至”，盖言顺也。直其正也，方其义也，君子敬以直内，义以方外， <a class="header-anchor" href="#易曰-履霜坚冰至-盖言顺也。直其正也-方其义也-君子敬以直内-义以方外" aria-label="Permalink to “易曰“履霜坚冰至”，盖言顺也。直其正也，方其义也，君子敬以直内，义以方外，”">​</a></h3><p>敬以直内则不失于物，义以方外则得己，敬义一道也。敬所以成仁也，盖敬则实为之，实为之故成其仁。</p><h3 id="敬义立而德不孤。-直方大-不习无不利-则不疑其所行也。阴虽有美-含之以从王事-弗敢成也-地道也-妻道也-臣道也-地道无成而代有终也。天地变化-草木蕃-天地闭-贤人隐。易曰-括囊无咎无誉-盖言谨也。君子黄中通理-正位居体-美在其中-而畅于四支-发于事业-美之至也。阴疑于阳必战-为其嫌于无阳也-故称龙焉-犹未离其类也-故称血焉。夫玄黄者-天地之杂也-天玄而地黄。" tabindex="-1">敬义立而德不孤。“直方大，不习无不利”，则不疑其所行也。阴虽有美，含之以从王事，弗敢成也，地道也，妻道也，臣道也，地道无成而代有终也。天地变化，草木蕃；天地闭，贤人隐。易曰“括囊无咎无誉”，盖言谨也。君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。阴疑于阳必战，为其嫌于无阳也，故称龙焉；犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。 <a class="header-anchor" href="#敬义立而德不孤。-直方大-不习无不利-则不疑其所行也。阴虽有美-含之以从王事-弗敢成也-地道也-妻道也-臣道也-地道无成而代有终也。天地变化-草木蕃-天地闭-贤人隐。易曰-括囊无咎无誉-盖言谨也。君子黄中通理-正位居体-美在其中-而畅于四支-发于事业-美之至也。阴疑于阳必战-为其嫌于无阳也-故称龙焉-犹未离其类也-故称血焉。夫玄黄者-天地之杂也-天玄而地黄。" aria-label="Permalink to “敬义立而德不孤。“直方大，不习无不利”，则不疑其所行也。阴虽有美，含之以从王事，弗敢成也，地道也，妻道也，臣道也，地道无成而代有终也。天地变化，草木蕃；天地闭，贤人隐。易曰“括囊无咎无誉”，盖言谨也。君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。阴疑于阳必战，为其嫌于无阳也，故称龙焉；犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。”">​</a></h3><p>正位居体，所以应黄裳之美。</p>',23)])])}const _=e(l,[["render",n]]);export{b as __pageData,_ as default};
